Parameters.script:
# CheckNewFiles - scan C:\temp\order-exec for unprocessed order CSVs.
# Emits: { hasNew, file (first pending path or null), pendingCount, filesInDrop }
$ErrorActionPreference = "Stop"
$dir = "C:\temp\order-exec"
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }

$marker = Join-Path $dir ".processed.json"
$processed = @()
if (Test-Path $marker) {
    try {
        $m = Get-Content $marker -Raw | ConvertFrom-Json
        if ($m) { foreach ($x in @($m)) { if ($x.file) { $processed += [string]$x.file } } }
    } catch {}
}

$candidates = @(Get-ChildItem -Path $dir -Filter *.csv -File | Where-Object { (([datetime]::UtcNow - $_.LastWriteTimeUtc).TotalSeconds -ge 10) })
$pending = @($candidates | Where-Object { $processed -notcontains $_.FullName })

return [pscustomobject]@{
    hasNew = ($pending.Count -gt 0)
    file = $(if ($pending.Count -gt 0) { $pending[0].FullName } else { $null })
    pendingCount = $pending.Count
    filesInDrop = @($candidates | ForEach-Object { $_.Name })
}

# ValidateStock - validate order lines against C:\temp\order-exec\orders.db.
# Input: { file, import: { enrichedRows: [ {OrderId, ProductId, Qty, CustomerName} ] } }
# Emits: { valid, errors[], orderId, customerName, lines[{productId,name,price,qty,lineTotal}], total, file }
$ErrorActionPreference = "Stop"

$file = [string]$input_data.file
$rows = @()
if ($input_data.import -and $input_data.import.enrichedRows) { $rows = @($input_data.import.enrichedRows) }
if ($rows.Count -eq 0) {
    return [pscustomobject]@{ valid=$false; errors=@("no rows in import result"); orderId=""; customerName=""; lines=@(); total=0.0; file=$file }
}

$orderId = [string]$rows[0].OrderId
$customerName = [string]$rows[0].CustomerName

# Parse and merge line items (sum qty per product).
$lines = @{}
$errors = @()
foreach ($r in $rows) {
    $pid_ = 0; $qty = 0
    if (-not [int]::TryParse([string]$r.ProductId, [ref]$pid_)) { $errors += ("row: ProductId not numeric: " + [string]$r.ProductId); continue }
    if (-not [int]::TryParse([string]$r.Qty, [ref]$qty) -or $qty -le 0) { $errors += ("row for product ${pid_}: Qty must be a positive integer"); continue }
    if ($lines.ContainsKey($pid_)) { $lines[$pid_] = $lines[$pid_] + $qty } else { $lines[$pid_] = $qty }
}

# Fetch all referenced products in one query.
$ids = (($lines.Keys | ForEach-Object { [string]$_ }) -join ",")
$dbq = Join-Path "C:\temp\order-exec" "dbq.py"
$sqlFile = Join-Path $env:TEMP ("sf_ordv_" + [guid]::NewGuid().ToString("N") + ".sql")
Set-Content -Path $sqlFile -Value ("SELECT id, name, price, stock, category, description FROM products WHERE id IN (" + $ids + ")") -Encoding UTF8
$pyOut = (& python $dbq $sqlFile 2>&1 | Out-String).Trim()
if ($LASTEXITCODE -ne 0) { throw ("catalog query failed: " + $pyOut) }
$db = $pyOut | ConvertFrom-Json
$byId = @{}
foreach ($p in @($db.rows)) { $byId[[int]$p.id] = $p }

$outLines = @()
$total = 0.0
foreach ($k in $lines.Keys) {
    if (-not $byId.ContainsKey([int]$k)) { $errors += ("product " + [string]$k + " not found"); continue }
    $p = $byId[[int]$k]
    if ([int]$p.stock -lt $lines[$k]) {
        $errors += ("insufficient stock for product " + [string]$k + " (" + $p.name + "): have " + $p.stock + ", need " + $lines[$k])
        continue
    }
    $lineTotal = [math]::Round([double]$p.price * $lines[$k], 2)
    $total += $lineTotal
    $outLines += [pscustomobject]@{ productId=[int]$k; name=[string]$p.name; price=[double]$p.price; qty=$lines[$k]; lineTotal=$lineTotal }
}

return [pscustomobject]@{
    valid = ($errors.Count -eq 0)
    errors = @($errors)
    orderId = $orderId
    customerName = $customerName
    lines = @($outLines)
    total = [math]::Round($total, 2)
    file = $file
}

# ReduceStock - finalize a successfully AI-processed order: verify + fix the invoice, then decrement stock.
# Input: { orderId, customerName, lines[{productId,name,price,qty,lineTotal}], total, file, ai }
# Runs AFTER AskAi succeeds so a failed AI run leaves no stock side effects; passes `ai` through to MarkProcessed.
$ErrorActionPreference = "Stop"

$file = [string]$input_data.file
$dbPath = Join-Path "C:\temp\order-exec" "orders.db"
if (-not (Test-Path $dbPath)) { throw ("database not found: " + $dbPath) }

# Verify the agent actually wrote the invoice before applying any side effects.
$invoice = Join-Path "C:\temp\order-exec\output" ("invoice-" + [string]$input_data.orderId + ".txt")
if (-not (Test-Path $invoice)) { throw ("invoice not found: " + $invoice) }

# Enforce the real UTC date on the invoice - the model hallucinates dates despite prompt instructions.
$text = Get-Content $invoice -Raw
$nowUtc = (Get-Date).ToUniversalTime().ToString("yyyy-MM-dd HH:mm:ss") + " UTC"
Set-Content -Path $invoice -Value ([regex]::Replace($text, "(?m)^Date:.*$", ("Date: " + $nowUtc))) -Encoding UTF8

$reduced = @()
foreach ($line in @($input_data.lines)) {
    $pid_ = [int]$line.productId
    $qty = [int]$line.qty
    $before = 0; $after = 0
    try {
        $before = [int](& python -c "import sqlite3;c=sqlite3.connect(r'$dbPath');print(c.execute('SELECT stock FROM products WHERE id=$pid_').fetchone()[0])" 2>&1 | Out-String).Trim()
        & python -c "import sqlite3;c=sqlite3.connect(r'$dbPath');c.execute('UPDATE products SET stock=stock-$qty WHERE id=$pid_ AND stock>=$qty');c.commit()" 2>&1 | Out-Null
        $after = [int](& python -c "import sqlite3;c=sqlite3.connect(r'$dbPath');print(c.execute('SELECT stock FROM products WHERE id=$pid_').fetchone()[0])" 2>&1 | Out-String).Trim()
    } catch {
        throw ("stock update failed for product ${pid_}: " + $_.Exception.Message)
    }
    if ($after -ge $before) { throw ("stock not decremented for product $pid_ (before=$before after=$after); refusing to continue") }
    $reduced += [pscustomobject]@{ productId=$pid_; name=[string]$line.name; qty=$qty; before=$before; after=$after }
}

return [pscustomobject]@{ orderId=[string]$input_data.orderId; customerName=[string]$input_data.customerName; lines=@($input_data.lines); total=[double]$input_data.total; file=$file; reduced=@($reduced); ai=$input_data.ai }

# AskAi - autonomous tool-calling agent that generates an invoice for a validated order.
# Input: { orderId, customerName, lines[{productId,name,price,qty,lineTotal}], total, file }
# Emits (merged at $.ai): { status, iterations, answer, toolLog }
# Throws on unrecoverable failure -> States.TaskFailed -> HandleFailure (no stock side effects).
$ErrorActionPreference = "Stop"

$model = "Ternary-Bonsai-27B-Q2_0.gguf"
$apiBase = "http://192.168.10.175:8080/v1"
$apiUrl = $apiBase + "/chat/completions"
$dbq = Join-Path "C:\temp\order-exec" "dbq.py"

function Trunc([string]$s) {
    if ($null -eq $s) { return "" }
    if ($s.Length -gt 1500) { return $s.Substring(0, 1500) + " ...[truncated]" }
    return $s
}

function Log([string]$msg) { [Console]::Error.WriteLine("[AskAi] " + $msg) }

# Wait until the AI server is healthy again: /v1/models lists a model AND a minimal completion returns choices.
# The local llama.cpp server intermittently 500s / answers empty under sustained load and recovers after a reload.
function Wait-ServerHealthy() {
    for ($w = 0; $w -lt 18; $w++) {   # ~3 minute budget: probe + 10s sleep per round
        try {
            $m = Invoke-RestMethod -Uri ($apiBase + "/models") -TimeoutSec 5 -ErrorAction Stop
            if (@($m.data).Count -gt 0) {
                $miniBody = '{"model":"' + $model + '","messages":[{"role":"user","content":"Say OK"}],"max_tokens":8,"temperature":0}'
                $mini = Invoke-RestMethod -Uri $apiUrl -Method Post -ContentType "application/json" -Body $miniBody -TimeoutSec 60 -ErrorAction Stop
                if ($mini.choices -and @($mini.choices).Count -gt 0) { return $true }
            }
        } catch {}
        Start-Sleep -Seconds 10
    }
    return $false
}

function Invoke-LocalTool([string]$name, [string]$argsJson) {
    if ($name -eq "query_db") {
        try {
            $q = (ConvertFrom-Json $argsJson).sql
            $out = & python "$dbq" $q 2>&1 | Out-String
            return ("rows: " + $out.Trim())
        } catch {
            return ('{"error":"query_db failed: ' + $_.Exception.Message.Replace('"', '\"') + '"}')
        }
    }
    if ($name -eq "write_file") {
        try {
            $p = (ConvertFrom-Json $argsJson).path
            $c = (ConvertFrom-Json $argsJson).content
            $dir = Split-Path $p -Parent
            if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
            Set-Content -Path $p -Value $c -Encoding UTF8
            return ('{"ok":true,"path":"' + $p.Replace('"', '\"') + '"}')
        } catch {
            return ('{"error":"write_file failed: ' + $_.Exception.Message.Replace('"', '\"') + '"}')
        }
    }
    return ('{"error":"unknown tool: ' + $name.Replace('"', '\"') + '"}')
}

$orderId = [string]$input_data.orderId
$orderInfo = [pscustomobject]@{
    orderId = $orderId
    customerName = [string]$input_data.customerName
    lines = @($input_data.lines)
    total = [double]$input_data.total
    dateUtc = (Get-Date).ToUniversalTime().ToString("yyyy-MM-dd HH:mm:ss") + " UTC"
}

$systemPrompt = @"
You are an order fulfillment assistant for a coffee equipment shop. You receive one validated customer order as JSON with fields: orderId, customerName, lines (array of {productId, name, price, qty, lineTotal}), total, dateUtc.
Your job:
1) Use query_db to look up full details for each ordered product from the products table (columns: id, name, price, stock, category, description).
2) Use query_db to find complementary products that pair well with what was purchased and are still in stock: SELECT DISTINCT p.id, p.name, p.price, p.description FROM complements c JOIN products p ON p.id = c.complement_id WHERE c.product_id IN (<ordered product ids>) AND p.stock > 0. Only recommend products not already part of this order.
3) Use write_file to create the invoice at C:\temp\order-exec\output\invoice-<orderId>.txt (substitute the actual orderId). The file must contain: a header with the word INVOICE, the orderId, customer name and the dateUtc value from the order JSON (do not invent any other date); an itemized list of each line as "name - qty x unit price = line total" plus a grand total in USD; a short friendly message about the purchased product(s) tailored to this order based on their descriptions; and a section titled "You might also like" listing 2-4 complementary products, each with a one-line reason it pairs well.
4) Reply with a brief plain-text summary: the invoice file path, the grand total, and which complementary products you recommended.
"@

$userMessage = "Order to process:`n" + ($orderInfo | ConvertTo-Json -Depth 10)

$tools = @(
    [pscustomobject]@{ type="function"; function=[pscustomobject]@{ name="query_db"; description="Run a read-only SQL query against the shop database (tables: products(id,name,price,stock,category,description), complements(product_id,complement_id)). Returns rows as text."; parameters=[pscustomobject]@{ type="object"; properties=[pscustomobject]@{ sql=[pscustomobject]@{ type="string"; description="The SQL SELECT statement" } }; required=@("sql") } } },
    [pscustomobject]@{ type="function"; function=[pscustomobject]@{ name="write_file"; description="Write text content to a file path (creates parent directories). Use for the invoice."; parameters=[pscustomobject]@{ type="object"; properties=[pscustomobject]@{ path=[pscustomobject]@{ type="string" }; content=[pscustomobject]@{ type="string" } }; required=@("path","content") } } },
    [pscustomobject]@{ type="function"; function=[pscustomobject]@{ name="verify_output_folder"; description="List the contents of C:\temp\order-exec\output to confirm files were written."; parameters=[pscustomobject]@{ type="object"; properties=@{}; required=@() } } }
)

$messages = @(
    [pscustomobject]@{ role="system"; content=$systemPrompt },
    [pscustomobject]@{ role="user"; content=$userMessage }
)

$toolLog = @()
$maxIter = 15
$maxAttempts = 3
$finalAnswer = ""
$i = 0

for ($i = 0; $i -lt $maxIter; $i++) {
    # Per-iteration retry: on API failure wait for the server to recover, then resend the same request.
    $resp = $null
    for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
        try {
            $body = [pscustomobject]@{ model=$model; messages=@($messages); tools=@($tools); tool_choice="auto"; max_tokens=4096; temperature=0.3 }
            $resp = Invoke-RestMethod -Uri $apiUrl -Method Post -ContentType "application/json" -Body ($body | ConvertTo-Json -Depth 20) -TimeoutSec 900
            if (-not $resp.choices -or @($resp.choices).Count -eq 0) {
                throw ("AI returned no choices: " + (Trunc (($resp | ConvertTo-Json -Depth 5))))
            }
            break
        } catch {
            if ($attempt -ge $maxAttempts) {
                throw ("execution failed at iteration " + ($i + 1) + " after " + $maxAttempts + " attempts: " + $_.Exception.Message)
            }
            Log ("iteration " + ($i+1) + " attempt " + $attempt + " failed: " + $_.Exception.Message + "; waiting for server recovery")
            Start-Sleep -Seconds 20
            if (-not (Wait-ServerHealthy)) { Log "server did not report healthy within budget; retrying anyway" }
        }
    }

    $choice = $resp.choices[0]
    $msg = $choice.message

    # Hashtable, not PSCustomObject: tool_calls is added conditionally and PS fixed objects reject new properties.
    $assistantMsg = @{ role="assistant"; content="" }
    if ($null -ne $msg.content) { $assistantMsg["content"] = [string]$msg.content }
    if ($msg.tool_calls) {
        $tcs = @()
        foreach ($tc in @($msg.tool_calls)) {
            $argsStr = "{}"
            if ($tc.function.arguments) { $argsStr = [string]$tc.function.arguments }
            $tcs += [pscustomobject]@{ id=[string]$tc.id; type="function"; function=[pscustomobject]@{ name=[string]$tc.function.name; arguments=$argsStr } }
        }
        $assistantMsg["tool_calls"] = @($tcs)
    }
    $messages += $assistantMsg

    if ($choice.finish_reason -eq "tool_calls" -and $msg.tool_calls) {
        foreach ($tc in @($msg.tool_calls)) {
            $tname = [string]$tc.function.name
            $argsStr = "{}"
            if ($tc.function.arguments) { $argsStr = [string]$tc.function.arguments }
            $tresult = Invoke-LocalTool $tname $argsStr
            $toolLog += [pscustomobject]@{ iteration=($i+1); tool=$tname; arguments=(Trunc $argsStr); result=(Trunc $tresult) }
            $messages += [pscustomobject]@{ role="tool"; tool_call_id=[string]$tc.id; content=$tresult }
        }
    } else {
        if ($msg.content) { $finalAnswer = [string]$msg.content }
        if ($choice.finish_reason -eq "length") { Log ("warning: final answer truncated at iteration " + ($i+1)) }
        break
    }
}

if ($i -ge $maxIter) { throw ("iteration limit reached after " + $maxIter + " iterations without a final answer") }

$status = "completed"
if ($resp.choices[0].finish_reason -eq "length") { $status = "truncated" }

return [pscustomobject]@{ status=$status; iterations=($i+1); answer=(Trunc $finalAnswer); toolLog=@($toolLog) }

# RejectOrder - order failed validation: write a rejection notice, record marker, move CSV to failed\.
# Input: { file, orderId, customerName, errors[] }
$ErrorActionPreference = "Stop"

$file = [string]$input_data.file
$orderId = if ($input_data.orderId) { [string]$input_data.orderId } else { "unknown" }
$errors = @($input_data.errors | ForEach-Object { [string]$_ })
if (-not $errors -or $errors.Count -eq 0) { $errors = @("validation failed (no detail)") }

$outDir = "C:\temp\order-exec\output"
if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }
$notice = Join-Path $outDir ("rejected-" + $orderId + ".txt")
$text = "ORDER REJECTION`nOrderId: $orderId`nCustomer: $($input_data.customerName)`nDate (UTC): $(Get-Date).ToUniversalTime().ToString('o')`n`nReasons:`n" + (($errors | ForEach-Object { "- $_" }) -join "`n")
Set-Content -Path $notice -Value $text -Encoding UTF8

$dir = "C:\temp\order-exec"
$s = ($errors -join "; ")
if ($s.Length -gt 2000) { $s = $s.Substring(0, 2000) + " ...[truncated]" }
$marker = Join-Path $dir ".processed.json"
$list = @()
if (Test-Path $marker) { try { $m = Get-Content $marker -Raw | ConvertFrom-Json; if ($m) { $list = @($m) } } catch {} }
$list += [pscustomobject]@{ file=$file; processedAt=(Get-Date).ToString("o"); aiStatus="rejected"; summary=$s }
$list | ConvertTo-Json -Depth 5 | Set-Content -Path $marker -Encoding UTF8

if (Test-Path $file) {
    $failedDir = Join-Path $dir "failed"
    if (-not (Test-Path $failedDir)) { New-Item -ItemType Directory -Path $failedDir -Force | Out-Null }
    Move-Item -Path $file -Destination (Join-Path $failedDir (Split-Path $file -Leaf)) -Force
}

return [pscustomobject]@{ ok=$true; orderId=$orderId; notice=$notice }

# MarkProcessed - record the processed order and move its CSV to processed\.
# Input: { file, orderId, ..., ai: { status, answer } }
$ErrorActionPreference = "Stop"

$file = [string]$input_data.file
$dir = "C:\temp\order-exec"

$status = "unknown"
if ($input_data.ai -and $input_data.ai.status) { $status = [string]$input_data.ai.status }
$summary = ""
if ($input_data.ai -and $input_data.ai.answer) { $summary = [string]$input_data.ai.answer }
if ($summary.Length -gt 2000) { $summary = $summary.Substring(0, 2000) + " ...[truncated]" }

# Move the CSV out of the drop folder first so a marker failure below cannot cause reprocessing.
$processedDir = Join-Path $dir "processed"
if (-not (Test-Path $processedDir)) { New-Item -ItemType Directory -Path $processedDir -Force | Out-Null }
Move-Item -Path $file -Destination (Join-Path $processedDir (Split-Path $file -Leaf)) -Force

$marker = Join-Path $dir ".processed.json"
$list = @()
if (Test-Path $marker) { try { $m = Get-Content $marker -Raw | ConvertFrom-Json; if ($m) { $list = @($m) } } catch {} }
$list += [pscustomobject]@{ file=$file; processedAt=(Get-Date).ToString("o"); aiStatus=$status; summary=$summary }
$list | ConvertTo-Json -Depth 5 | Set-Content -Path $marker -Encoding UTF8

return [pscustomobject]@{ ok=$true; status=$status }

# HandleFailure - catch-all for state failures: move CSV to failed\ and record a marker.
# Input: { file, orderId?, failError: { error, cause? }, ... }
$ErrorActionPreference = "Stop"

$file = [string]$input_data.file
$dir = "C:\temp\order-exec"

$reason = "unknown failure"
if ($input_data.failError -and $input_data.failError.error) { $reason = [string]$input_data.failError.error }
elseif ($input_data.failError) { $reason = ([pscustomobject]$input_data.failError | ConvertTo-Json -Depth 5 -Compress) }
if ($reason.Length -gt 2000) { $reason = $reason.Substring(0, 2000) + " ...[truncated]" }

$failedDir = Join-Path $dir "failed"
if (-not (Test-Path $failedDir)) { New-Item -ItemType Directory -Path $failedDir -Force | Out-Null }
if (Test-Path $file) { Move-Item -Path $file -Destination (Join-Path $failedDir (Split-Path $file -Leaf)) -Force }

$marker = Join-Path $dir ".processed.json"
$list = @()
if (Test-Path $marker) { try { $m = Get-Content $marker -Raw | ConvertFrom-Json; if ($m) { $list = @($m) } } catch {} }
$list += [pscustomobject]@{ file=$file; processedAt=(Get-Date).ToString("o"); aiStatus="failed"; summary=$reason }
$list | ConvertTo-Json -Depth 5 | Set-Content -Path $marker -Encoding UTF8

return [pscustomobject]@{ ok=$true; reason=$reason }
